"use client";

import { Download, FileText } from "lucide-react";
import { useEffect, useState } from "react";

import { NoticeDialog } from "@/components/modals/confirm-dialog";
import { Button } from "@/components/ui/button";
import { Dialog } from "@/components/ui/dialog";
import { safeFileSegment } from "@/lib/format";
import { downloadReportPdf } from "@/services/cases";

// The forensic PDF is generated by the backend (GET /cases/{id}/results).
// The browser previews it in a dialog and saves it with the mobile file name.

function triggerDownload(blob: Blob, fileName: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

export function ReportActions({
  caseId,
  caseCode,
  allowed,
  disabledReason,
}: {
  caseId: string;
  caseCode: string;
  allowed: boolean;
  disabledReason: string;
}) {
  const [busy, setBusy] = useState<"preview" | "download" | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [blob, setBlob] = useState<Blob | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileName = `AVERA_Forensic_Report_${safeFileSegment(caseCode || caseId)}.pdf`;

  useEffect(() => () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
  }, [previewUrl]);

  const fetchReport = async () => {
    try {
      const pdf = await downloadReportPdf(caseId);
      setBlob(pdf);
      return pdf;
    } catch (fetchError) {
      setError(
        fetchError instanceof Error && /not ready|not enabled/i.test(fetchError.message)
          ? fetchError.message
          : "The PDF report is either still generating or unavailable.",
      );
      return null;
    }
  };

  const preview = async () => {
    setBusy("preview");
    const pdf = blob ?? (await fetchReport());
    setBusy(null);
    if (pdf) setPreviewUrl(URL.createObjectURL(pdf));
  };

  const download = async () => {
    setBusy("download");
    const pdf = blob ?? (await fetchReport());
    setBusy(null);
    if (pdf) triggerDownload(pdf, fileName);
  };

  return (
    <>
      <div className="flex flex-wrap items-center gap-2">
        <Button
          variant="secondary"
          icon={<FileText className="size-4" />}
          onClick={() => void preview()}
          loading={busy === "preview"}
          disabled={!allowed || busy !== null}
          title={allowed ? undefined : disabledReason}
        >
          Preview report
        </Button>
        <Button
          icon={<Download className="size-4" />}
          onClick={() => void download()}
          loading={busy === "download"}
          disabled={!allowed || busy !== null}
          title={allowed ? undefined : disabledReason}
        >
          {allowed ? "Export PDF" : "PDF export disabled"}
        </Button>
      </div>

      <Dialog
        open={previewUrl !== null}
        onClose={() => {
          if (previewUrl) URL.revokeObjectURL(previewUrl);
          setPreviewUrl(null);
        }}
        size="full"
        title="Forensic report"
        description={fileName}
        bodyClassName="px-0 sm:px-0 pb-0"
        footer={
          <Button icon={<Download className="size-4" />} onClick={() => blob && triggerDownload(blob, fileName)}>
            Download PDF
          </Button>
        }
      >
        {previewUrl ? <iframe src={previewUrl} title="Forensic report preview" className="h-[70dvh] w-full border-y border-line bg-sunken" /> : null}
      </Dialog>

      <NoticeDialog open={error !== null} onClose={() => setError(null)} tone="error" title="Export failed" message={error ?? ""} />
    </>
  );
}
